from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class Nrdrb5qiParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        bts_id = self.enb_ent_config['id']
        if self.is_sa_nsa:
            num = int(self.mo_num)
            if num < 6:
                self.set_parameter('fiveqiValueList', num + 4)
            else:
                self.set_parameter('fiveqiValueList', '1')

        if self.is_sa:
            num = int(self.mo_num)
            if num < 6:
                self.set_parameter('fiveqiValueList', num + 4)
            else:
                self.set_parameter('fiveqiValueList', '1')

        nrdrb_num = int(self.mo_num) + 9
        self.set_parameter('nrDrbDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRB-{nrdrb_num}')
